      ],
      "materiality_rationale": "Removing or changing this definition changes the workload boundary identified by the primary assertion.",
      "resolution_rationale": "The reference preserves the supplied value and units without asserting that harm begins precisely there or prescribing any action."
    },
    {
      "dependency_id": "R3K09-C1-D3",
      "subject": "Controlled paired runs, holding software and traffic mix fixed, recorded 1 error per 1000 requests below T and 120 errors per 1000 above T across each of ten replications.",
